// ───────────────────────────────────────────────
// EDIT YOUR INPUTS HERE
// ───────────────────────────────────────────────
return [{
  json: {
    // Backend + admin credentials
    baseUrl:       'http://localhost:8080',
    adminEmail:    'admin@example.com',
    adminPassword: 'CHANGE_ME',

    // Language used to look up the category by name (AZ | EN | AR)
    lang: 'EN',

    // The product code you assign manually (must be globally unique)
    sku: 'DTAX0993',

    // ACCESSORY -> DTAX convention | SIMPLE / DIY -> DTDX
    productType: 'ACCESSORY',

    // Category is SELECTED by matching this name in GET /api/category
    categoryName: 'Headphones',

    // Spec is SELECTED from GET /api/admin/specs:
    //   - match the group by its `code`
    //   - match the option by its EN `value`
    // Set spec to null if this product has no spec.
    spec: { code: 'ram', value: '16' },

    // Required translations (all three languages, non-blank)
    translations: {
      titleAz: 'Yeni Məhsul',
      titleEn: 'New Product',
      titleAr: 'منتج جديد',
      descriptionAz: 'Təsvir',
      descriptionEn: 'Description',
      descriptionAr: 'وصف'
    }
  }
}];

const input  = $('Set Input').item.json;

// ── Select the category by name ───────────────────────────────
const cats = ($('Get categories').item.json.data) || [];
const cat  = cats.find(c => c.name === input.categoryName);
if (!cat) {
  throw new Error('Category not found: "' + input.categoryName + '". Available: ' + cats.map(c => c.name).join(', '));
}

// ── Select the spec group + option ────────────────────────────
const groups = ($('Get specs').item.json.data) || [];
const specs  = [];
if (input.spec && input.spec.code) {
  const g = groups.find(x => x.code === input.spec.code);
  if (!g) throw new Error('Spec group not found: "' + input.spec.code + '". Available codes: ' + groups.map(x => x.code).join(', '));
  const opt = (g.options || []).find(o =>
    (o.translations || []).some(t => String(t.value) === String(input.spec.value)));
  if (!opt) throw new Error('Spec option "' + input.spec.value + '" not found in group "' + input.spec.code + '"');
  specs.push({
    globalSpecGroupId: g.id,
    options: [{ localKey: 'opt-1', globalOptionId: opt.id }]
  });
}

// ── Assemble the create-product request payload ───────────────
const productRequest = {
  categoryId:   cat.id,
  productType:  input.productType,
  sku:          input.sku,
  translations: input.translations,
  specs:        specs
};

return [{ json: { productRequest } }];
